function n(t){return t<10?`0${t}`:String(t)}function r(t){return new Date(t*1e3)}function a(t){const e=r(t);return`${e.getFullYear()}-${n(e.getMonth()+1)}-${n(e.getDate())} ${n(e.getHours())}:${n(e.getMinutes())}`}function i(t){const e=r(t);return`${e.getFullYear()}-${n(e.getMonth()+1)}-${n(e.getDate())}`}function c(t){const e=r(t);return`${n(e.getHours())}:${n(e.getMinutes())}`}const u=["星期日","星期一","星期二","星期三","星期四","星期五","星期六"];function g(){const t=new Date;return`${t.getFullYear()}-${n(t.getMonth()+1)}-${n(t.getDate())} ${u[t.getDay()]}`}function s(t){return t.toLocaleString("en-US")}function f(t,e=!0){const o=t.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2});return e?`¥${o}`:o}function $(){const t=new Date().getHours();return t<6?"凌晨好":t<12?"上午好":t<14?"中午好":t<18?"下午好":"晚上好"}export{f as a,a as b,i as c,c as d,s as e,g as f,$ as g};
